 79 │ /** Submodule levels `nestedRepositoryReason` walks before refusing rather than guessing. */
 80 │ const MAX_SUBMODULE_DEPTH = 4;
 81 │ /** Entries read in untracked directories while looking for a planted repository, and the size of a file listing. */
 82 │ const MAX_UNTRACKED_ENTRIES_SCANNED = 100_000;
 83 │ const LISTING_BUFFER = 256 * 1024 * 1024;
