 88 │  * runs before every status. Undefined when `dir` is not an agent-writable checkout or nothing is wrong.
 89 │  */
 90 │ export function nestedRepositoryReason(dir: string, depth = 0): string | undefined {
 91 │   const own = verifyCheckout(dir);
 92 │   if (own.reason) return own.reason;
 93 │   if (!own.gitDir) return undefined;
 94 │   if (depth > MAX_SUBMODULE_DEPTH) return `submodules are nested more than ${MAX_SUBMODULE_DEPTH} levels deep below ${dir}`;
 95 │   const candidates = new Set<string>();
 96 │   // Large trees: the listings can be long, and one that does not fit is a refusal, not a pass.
 97 │   const listing = (args: string[]) => git(dir, args, { maxBuffer: LISTING_BUFFER }).stdout.split("\0");
