 85 │ /**
 86 │  * Whether a repository the agent could have planted sits below `dir`: a gitlink in the index or an untracked directory
 87 │  * holding a `.git`. Git itself descends into submodules when it reports status, reading their configuration, so this
 88 │  * runs before every status. Undefined when `dir` is not an agent-writable checkout or nothing is wrong.
 89 │  */
 90 │ export function nestedRepositoryReason(dir: string, depth = 0): string | undefined {
 91 │   const own = verifyCheckout(dir);
 92 │   if (own.reason) return own.reason;
 93 │   if (!own.gitDir) return undefined;
 94 │   if (depth > MAX_SUBMODULE_DEPTH) return `submodules are nested more than ${MAX_SUBMODULE_DEPTH} levels deep below ${dir}`;
 95 │   const candidates = new Set<string>();
 96 │   // Large trees: the listings can be long, and one that does not fit is a refusal, not a pass.
 97 │   const listing = (args: string[]) => git(dir, args, { maxBuffer: LISTING_BUFFER }).stdout.split("\0");
 98 │   // Paths are decoded as UTF-8: bytes that are not valid become U+FFFD and name nothing on disk, so such a path could
 99 │   // hide a planted repository from this check while Git still descends into it. It is refused, not skipped.
100 │   const undecodable = (name: string) => name.includes("\uFFFD");
101 │   for (const entry of listing(["ls-files", "-s", "-z"])) {
102 │     if (undecodable(entry)) return `a tracked path below ${dir} is not valid UTF-8; it cannot be checked for a planted repository`;
103 │     const tab = entry.indexOf("\t"); // the path follows the first tab and may itself contain any character, a newline included
104 │     if (tab > 0 && /^160000 [0-9a-f]+ \d$/.test(entry.slice(0, tab))) candidates.add(entry.slice(tab + 1));
105 │   }
106 │   // `--directory` keeps the listing short; Git collapses an untracked directory into one `dir/` entry, so a repository
107 │   // planted anywhere below it is looked for on disk, within a budget.
108 │   let budget = MAX_UNTRACKED_ENTRIES_SCANNED;
109 │   // Git never reads a repository inside an ignored directory (`node_modules`) when it reports status: not scanned, not counted.
110 │   const ignored = new Set(listing(["ls-files", "-o", "-i", "--exclude-standard", "--directory", "-z"]).filter((entry) => entry.endsWith("/")).map((entry) => path.join(dir, entry.slice(0, -1))));
111 │   for (const entry of listing(["ls-files", "-o", "--exclude-standard", "--directory", "-z"])) {
112 │     if (undecodable(entry)) return `an untracked path below ${dir} is not valid UTF-8; it cannot be checked for a planted repository`;
113 │     if (!entry.endsWith("/")) continue;
114 │     const found = gitDirectoriesBelow(path.join(dir, entry), budget, ignored);
115 │     if (found === undefined) return `more than ${MAX_UNTRACKED_ENTRIES_SCANNED} entries sit in untracked directories below ${dir}; none can be checked for a planted repository`;
116 │     if (found.undecodable !== undefined) return `a path below ${dir} is not valid UTF-8; it cannot be checked for a planted repository`;
117 │     budget -= found.scanned;
118 │     for (const repo of found.repos) candidates.add(path.relative(dir, repo));
119 │   }
120 │   for (const rel of candidates) {
121 │     const sub = path.join(dir, rel);
122 │     try { fs.lstatSync(path.join(sub, ".git")); } catch { continue; } // an ordinary directory, or a submodule not initialised here
123 │     const reason = nestedRepositoryReason(sub, depth + 1); // a planted repository can sit below a legitimate submodule too
124 │     if (reason) return reason;
125 │   }
126 │   return undefined;
127 │ }
