129 │ /** Directories at or below `root` that hold a `.git`, and how many entries were read; undefined when `budget` runs out. */
130 │ function gitDirectoriesBelow(root: string, budget: number, skip: ReadonlySet<string>): { repos: string[]; scanned: number; undecodable?: string } | undefined {
131 │   const repos: string[] = [];
132 │   const pending = [root];
133 │   let scanned = 0;
134 │   while (pending.length > 0) {
135 │     const dir = pending.pop()!;
136 │     let names: fs.Dirent[];
137 │     try { names = fs.readdirSync(dir, { withFileTypes: true }); } catch { continue; }
138 │     for (const entry of names) {
139 │       if (++scanned > budget) return undefined;
140 │       if (entry.name.includes("\uFFFD")) return { repos, scanned, undecodable: path.join(dir, entry.name) };
141 │       if (entry.name === ".git") repos.push(dir);
142 │       else if (entry.isDirectory() && !skip.has(path.join(dir, entry.name))) pending.push(path.join(dir, entry.name));
143 │     }
144 │   }
145 │   return { repos, scanned };
146 │ }
