164 │ export function git(cwd: string, args: readonly string[], options: GitOptions = {}): GitResult {
165 │   const checkout = verifyCheckout(cwd);
166 │   if (checkout.reason) throw new UntrustedCheckoutError(cwd, checkout.reason, args);
167 │   const pin = checkout.gitDir ? ["--git-dir", checkout.gitDir, "--work-tree", checkout.workTree!] : [];
168 │   const result = spawnSync("git", [...PINNED_GIT_FLAGS, ...pin, ...args], {
169 │     cwd,
170 │     encoding: "utf8",
171 │     stdio: ["pipe", "pipe", "pipe"],
172 │     input: options.input ?? "",
173 │     env: { ...baseEnv(), ...(options.env ?? {}) },
174 │     timeout: options.timeoutMs ?? 30_000,
175 │     maxBuffer: options.maxBuffer ?? 32 * 1024 * 1024,
176 │   });
177 │   const timedOut = (result.error as NodeJS.ErrnoException | undefined)?.code === "ETIMEDOUT";
178 │   const out: GitResult = { status: result.status, stdout: result.stdout ?? "", stderr: result.stderr ?? "", timedOut };
179 │   if (result.error && !timedOut) throw new GitError(`git could not run: ${(result.error as Error).message}`, null, args);
180 │   if (!options.allowFailure && (timedOut || result.status !== 0)) {
181 │     const detail = timedOut ? "timed out" : redactSecrets(out.stderr.trim().split("\n")[0] ?? "").slice(0, 300);
