197 │   return {
198 │     repo,
199 │     source: source as WorktreeEntry & { branch: string },
200 │     branch,
201 │     targetName,
202 │     targetEntry,
203 │     targetSha,
204 │     state,
205 │     gateState,
206 │     waiver,
207 │     mergeBase,
208 │     ahead,
209 │   };
210 │ }
